import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.CCylkYel.js";const u=JSON.parse('{"title":"S32 User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function n(i,e,d,h,l,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="s32-user-manual" tabindex="-1">S32 User Manual <a class="header-anchor" href="#s32-user-manual" aria-label="Permalink to &quot;S32 User Manual&quot;">​</a></h1><p>The S32 is a MIDI controller and processor: 32 knobs you name and map, and racks of MIDI devices that arpeggiate, sequence and reshape what you play.</p><p>Everything happens on the S32 itself. You can also shape your setups on a computer with the <a href="https://editor.shik.tech" target="_blank" rel="noreferrer">S32 editor</a>.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li><strong>Knobs your way.</strong> Name each knob and give it up to four <a href="./macros/">macros</a>: CC, 14-bit CC, NRPN, program change, SysEx, or any device setting.</li><li><strong>MIDI processing.</strong> 8 <a href="./racks/">racks</a> per project, each a chain of up to 10 <a href="./devices/">devices</a>: arpeggiator, step sequencer, Euclid, scaler, harmony, delay, filters and more.</li><li><strong>Deep modulation.</strong> 16 <a href="./lfos/">LFOs</a> on device settings, on knobs, or on other LFOs.</li><li><strong>Snapshots.</strong> Store knobs, racks and LFOs; recall them, <a href="./snapshots/morph">morph</a> between them, or play them as a song with <a href="./snapshots/lanes">Arrange</a>.</li><li><strong>Connections.</strong> USB, USB Host, two MIDI outs, MIDI in and thru (<a href="./getting-started/hardware">Hardware</a>).</li></ul><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><a href="./getting-started/quick-start">Quick Start</a> — make your first sound</li><li><a href="./navigation/controls">Controls</a> — editing values, side menus, Select + Back</li><li><a href="./navigation/main-menu">Main Menu</a> — where everything lives</li><li><a href="./perform/knob-view">Perform View</a> — the knobs, names and values you play with</li></ul><h2 id="find-a-topic" tabindex="-1">Find a topic <a class="header-anchor" href="#find-a-topic" aria-label="Permalink to &quot;Find a topic&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Pages</th></tr></thead><tbody><tr><td>Knobs, macros and edit mode</td><td><a href="./perform/knob-view">Perform</a> · <a href="./macros/">Macros</a></td></tr><tr><td>Racks and every MIDI device</td><td><a href="./racks/">Racks</a> · <a href="./devices/">Devices</a></td></tr><tr><td>Movement over time</td><td><a href="./lfos/">S32 LFOs</a> · <a href="./concepts/modulation">Modulation</a></td></tr><tr><td>Recall and songs</td><td><a href="./snapshots/">Snapshots</a> · <a href="./snapshots/lanes">Arrange</a></td></tr><tr><td>Controllers and ports</td><td><a href="./concepts/mapping">Mapping</a> · <a href="./concepts/routing">Routing</a></td></tr><tr><td>Save and set up</td><td><a href="./projects/">Projects</a> · <a href="./settings/">Settings</a></td></tr></tbody></table><h2 id="developers" tabindex="-1">Developers <a class="header-anchor" href="#developers" aria-label="Permalink to &quot;Developers&quot;">​</a></h2><p>The <a href="/developers/">s32 CLI</a> drives the S32 from a terminal.</p>',11)])])}const f=a(s,[["render",n]]);export{u as __pageData,f as default};
